mod audio;mod game;mod video;use game::Game;
fn main(){let mut captures=vec![];for (stage,typ,handler) in [(0,9,0x877c),(1,32,0x8f93),(2,37,0x9765),(4,23,0xaeed),(5,69,0xb63c)]{for difficulty in [0,2]{for blocked in [false,true]{let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x27]=6;g.memory[0x33]=difficulty;g.memory[0x30]=stage;g.memory[0x720]=typ;let mut samples=vec![];for tick in 0..1800 {let full=blocked && tick%11<2;for i in 1..16 {g.memory[0x720+i]=if full{1}else{0};}g.memory[0x1a]=tick as u8;if g.memory[0x720]!=0 {g.actor_call(handler,0).unwrap();}let mut spawns=vec![];if !full {for i in 1..16{if g.memory[0x720+i]!=0{spawns.push(serde_json::json!({"source_type":g.memory[0x720+i],"variant":g.memory[0x690+i],"x":g.memory[0x710+i] as u16+u16::from(g.memory[0x6f0+i])*256,"y":g.memory[0x560+i]}));}}}samples.push(serde_json::json!({"tick":tick,"full":full,"alive":g.memory[0x720]!=0,"phase":g.memory[0x520]&127,"spawns":spawns}));}captures.push(serde_json::json!({"stage":stage,"difficulty":difficulty,"blocked":blocked,"samples":samples}));}}}println!("{}",serde_json::to_string(&captures).unwrap());}
